// Why Code: the fixed check every plan must pass before any search uses it (the model alone dropped whole topics on 22, 25 and 26 Nov).
const s = $('Store Settings').first().json;
const inp = $('When Called By Workflow').first().json;
const out = $input.first().json.output || {};
const otherScript = /[Ͱ-῿　-￿]/; // Greek, Cyrillic, Arabic, CJK and other scripts
const latinTopic = !otherScript.test(String($('When Called By Workflow').first().json.keyword || ''));
// HTML codes back to characters, then items with markup are dropped: a model glitch (26 Nov, Kimi wrote "NE &lt;NEAR&gt;").
const unhtml = (w) => String(w).replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&nbsp;/gi, ' ');
const words = (g) => [...new Set([].concat(g || []).map(w => unhtml(w).replace(/["()#]/g, '').trim()).filter(w => w.length >= 2 && !/[<>{}\[\]|\\]/.test(w) && !(latinTopic && otherScript.test(w))))]; // one letter (B, M) matches almost any post; another script is a model glitch (26 Nov: "交易")
let angles = [].concat(out.angles || []).map(a => ({ keyword: inp.keyword, angle: String(a.angle || '').trim(), search_phrase: String(a.search_phrase || '').trim(),
  trends_term: String(a.trends_term || '').trim(), word_groups: [].concat(a.word_groups || []).map(words).filter(g => g.length >= 2).slice(0, 3) }))
  .filter(a => a.angle && a.search_phrase && a.word_groups.length >= 2);
const wide = angles.find(a => /^all news on/i.test(a.angle));
if (wide) angles = [wide, ...angles.filter(a => a !== wide)];
angles = angles.slice(0, s.angles);
const ok = !!wide && angles.length >= s.min_angles;
const reason = ok ? '' : !wide ? 'no wide angle ("All news on ...")' : `only ${angles.length} usable angles (at least ${s.min_angles} needed)`;
let old = []; try { old = (JSON.parse(inp.current_plan || '[]') || []).map(a => a.angle); } catch (e) { old = []; }
const now = angles.map(a => a.angle);
return [{ json: { ok, keyword: inp.keyword, reason, angles: ok ? angles : [],
  added: ok ? now.filter(x => !old.includes(x)) : [], removed: ok && old.length ? old.filter(x => !now.includes(x)) : [] } }];

